//chain of command
void initValue(SalesType _salesType)
{
    next initValue(_salesType);

    this.RRBBookTable = this.salesTable().RRBBookTable;
}

public Common RRBFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(RRBBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.RRBGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(RRBBookTable, Author));

    return refTableLookup.performFormLookup();
}
